CREATE FUNCTION "search_join"(p1 text, p2 text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $fn$
SELECT concat_ws(chr(1), NULLIF(fold_search(p1), ''), NULLIF(fold_search(p2), ''))
$fn$;
