-- search_compact(x) = the legacy `compact`: folded with the spaces removed ("REC-2026-000031" -> "rec2026000031").
CREATE FUNCTION "search_compact"(input text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $fn$
SELECT replace(fold_search(input), ' ', '')
