-- The forms an amount can be typed in (legacy 38-payment-search `amount`): 1000.5 -> "1000.5", "1,000.5", "1000.50",
-- "1,000.50", each already folded (the forms hold only digits, "." and ","; every "." / "," is a separator). Plain
-- expressions on purpose: the planner inlines this, where a CTE-bodied function costs over a millisecond per row.
CREATE FUNCTION "search_amount_text"(amount_p bigint) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $fn$
SELECT concat_ws(chr(1),
  (amount_p / 100)::text || COALESCE(' ' || NULLIF(rtrim(lpad((amount_p % 100)::text, 2, '0'), '0'), ''), ''),
  translate(to_char(amount_p / 100, 'FM999,999,999,999,999,999'), ',', ' ') || COALESCE(' ' || NULLIF(rtrim(lpad((amount_p % 100)::text, 2, '0'), '0'), ''), ''),
  CASE WHEN amount_p % 100 <> 0 THEN (amount_p / 100)::text || ' ' || lpad((amount_p % 100)::text, 2, '0') END,
  CASE WHEN amount_p % 100 <> 0 THEN translate(to_char(amount_p / 100, 'FM999,999,999,999,999,999'), ',', ' ') || ' ' || lpad((amount_p % 100)::text, 2, '0') END)
$fn$;
