-- The forms a business date can be typed in (legacy 33-invoice-search `dateText`), already folded:
-- "2026 09 05", "5 sep 2026", "september", "05 09 2026", "5 9 2026". Month names are spelled out (never to_char names,
-- which follow lc_time).
CREATE FUNCTION "search_date_text"(d date) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $fn$
SELECT concat_ws(chr(1),
  to_char(d, 'YYYY MM DD'),
  to_char(d, 'FMDD') || ' ' || (ARRAY['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'])[extract(month from d)::int] || ' ' || to_char(d, 'YYYY'),
  (ARRAY['january','february','march','april','may','june','july','august','september','october','november','december'])[extract(month from d)::int],
  to_char(d, 'DD MM YYYY'),
  to_char(d, 'FMDD FMMM YYYY'))
$fn$;
--> statement-breakpoint
